const dialog=document.querySelector('#project-dialog');const content=document.querySelector('.dialog-body');let lastTrigger;
function el(tag,text,cls){const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;}
document.querySelectorAll('.project-open').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.caseUrl){location.href=button.dataset.caseUrl;return;}const c=cases[button.dataset.project];lastTrigger=button;content.replaceChildren();content.append(el('p',c.org,'eyebrow'),el('h2',c.name));content.lastChild.id='dialog-title';content.append(el('p',c.role,'role'),el('p',c.intro));if(c.image){const img=el('img');img.src=c.image;img.alt=c.alt;content.append(img);}c.sections.forEach(([title,text])=>content.append(el('h3',title),el('p',text)));content.append(el('h3','Explore the evidence'));const list=el('ul',null,'evidence-links');c.links.forEach(([name,url])=>{const li=el('li');const a=el('a',name+' ↗');a.href=url;a.target='_blank';a.rel='noopener';li.append(a);list.append(li)});content.append(list,el('p',c.note,'evidence-note'));dialog.showModal();document.body.classList.add('modal-open');dialog.scrollTop=0;}));
document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close()});dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');lastTrigger?.focus()});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});let count=0;document.querySelectorAll('.project').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&!card.dataset.category.split(' ').includes(button.dataset.filter);if(!card.hidden)count++});document.querySelector('#filter-status').textContent=count+' projects shown';}));
const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('#nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}));document.querySelector('#year').textContent=new Date().getFullYear();
